// Connections come from PLUGGY_ITEM_IDS, in the n8n environment (same format as Ember's .env):
// "banco_a:<itemId>,banco_b:<itemId>". Connect through MeuPluggy: those itemIds do not expire.
// GET /items without an id does not list (it is not a listing route), so the list comes from configuration.
// n8n must let the Code node read the environment (N8N_BLOCK_ENV_ACCESS_IN_NODE=false).
const apiKey = $input.first().json.apiKey;
const raw = $env.PLUGGY_ITEM_IDS;
if (!raw) throw new Error('Missing PLUGGY_ITEM_IDS in the n8n environment (e.g. banco_a:<itemId>,banco_b:<itemId>)');
const SOURCE = /^[a-z0-9_]{1,30}$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const items = raw.split(',').map((p) => p.trim()).filter(Boolean).map((p) => {
  const i = p.indexOf(':');
  const source = p.slice(0, i).trim();
  const itemId = p.slice(i + 1).trim().toLowerCase();
  if (i < 0 || !SOURCE.test(source) || !UUID.test(itemId)) {
    throw new Error('Invalid PLUGGY_ITEM_IDS: use source:itemId separated by commas');
  }
  return { source, itemId };
});
return items.map((it) => ({ json: { ...it, apiKey } }));

// Pages /v2/transactions by cursor (the 'next' field, not 'page'/'pageSize').
// GET /transactions was deprecated in favor of this one.
// 'next' is the WHOLE query string of the next page ('?accountId=...&after=...'),
// not a loose token: use it as is, never build '&cursor=' on top of it.
// Window: last 15 days, the upsert happens in the next node via dedup_hash.
const crypto = require('crypto');
const apiKey = $json.apiKey;
const accountId = $json.id;
const source = $json.source;

const fifteenDaysAgo = new Date(Date.now() - 15 * 24 * 60 * 60 * 1000)
  .toISOString()
  .slice(0, 10);

let url = `https://api.pluggy.ai/v2/transactions?accountId=${accountId}`;
const all = [];

while (url) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'X-API-KEY': apiKey },
    json: true,
  });
  all.push(...resp.results);
  url = resp.next ? `https://api.pluggy.ai/v2/transactions${resp.next}` : null;
}

const recent = all.filter((t) => (t.date || '').slice(0, 10) >= fifteenDaysAgo);

// Identical transactions on the same day (two R$230 Pix to the same recipient) have different IDs
// at Pluggy but the same hash. Without a tiebreaker they merge in the upsert.
// The ordinal counts the occurrence inside the group, in the order the API returns them.
// Assumption: the API order is stable between runs.
const seen = new Map();

return recent.map((t) => {
  const installment = t.creditCardMetadata ? t.creditCardMetadata.installmentNumber : null;
  const descriptionRaw = t.descriptionRaw || '';
  const dateStr = (t.date || '').slice(0, 10);
  const base = [accountId, dateStr, String(t.amount), descriptionRaw, installment != null ? String(installment) : '0'].join('|');
  const ordinal = seen.get(base) || 0;
  seen.set(base, ordinal + 1);
  const dedupHash = crypto.createHash('md5').update(base + '|' + ordinal).digest('hex');

  return {
    json: {
      dedup_hash: dedupHash,
      pluggy_transaction_id: t.id,
      date: dateStr,
      accrual_date: dateStr,
      amount: t.amount,
      description_raw: descriptionRaw,
      description: t.description || null,
      source,
      movement_type: t.creditCardMetadata ? 'credit_card' : 'account',
      account_id: accountId,
      installment_number: installment,
      installments_total: t.creditCardMetadata ? t.creditCardMetadata.totalInstallments : null,
      bill_id: t.creditCardMetadata ? t.creditCardMetadata.billId : null,
      payload: t,
    },
  };
});
